using System;
using System.Windows.Forms;
using UCSPyayStudentRegistration.Database;
namespace UCSPyayStudentRegistration { static class Program { [STAThread] static void Main(string[] args) { Application.EnableVisualStyles(); Application.SetCompatibleTextRenderingDefault(false); try { DatabaseInitializer.EnsureDatabase();if(args.Length==1&&args[0]=="--self-test"){using(var a=new Forms.FrmAdmissionList()){}using(var r=new Forms.FrmSemesterResults()){}using(var x=new Forms.FrmApplications()){}using(var f=new Forms.FrmRefundManagement()){}using(var s=new Forms.FrmSystemSettings()){}using(var d=new Forms.FrmDataManagement()){}using(var m=new Forms.FrmStudentManagement()){}using(var w=new Forms.FrmApplicationWizard(1,"PYAY-2026-001")){}Environment.ExitCode=new Queries.UserQuery().Authenticate("admin","Admin@123")?0:2;return;}if(args.Length==1&&args[0]=="--workflow-test"){Tests.WorkflowSelfTest.Run();return;}Application.Run(new Forms.FrmWelcome()); } catch(Exception ex) {if(args.Length>0){try{System.IO.File.WriteAllText(System.IO.Path.Combine(Application.StartupPath,"self-test-error.txt"),ex.ToString());}catch{}Environment.ExitCode=1;return;}MessageBox.Show("The database could not be prepared.\r\n" + ex.Message, "Startup Error", MessageBoxButtons.OK, MessageBoxIcon.Error); } } } }
